import{_ as r,o as a,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Supporting a 3 Availability Zones Stretch Cluster. Kamoltat (Junior) Sirivadhna from IBM","description":"","frontmatter":{"title":"Supporting a 3 Availability Zones Stretch Cluster. Kamoltat (Junior) Sirivadhna from IBM","date":"2025-05-08T00:00:00.000Z","updated":"2025-05-08T00:00:00.000Z","tags":["Ceph","Distributed Storage","High Availability","Data Integrity","Cluster Scalability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Supporting_a_3_Availability_Zones_Stretch_Cluster._Kamoltat_Junior_Sirivadhna_from_IBM.md","filePath":"posts/2025/Supporting_a_3_Availability_Zones_Stretch_Cluster._Kamoltat_Junior_Sirivadhna_from_IBM.md","lastUpdated":1780459816000}'),l={name:"posts/2025/Supporting_a_3_Availability_Zones_Stretch_Cluster._Kamoltat_Junior_Sirivadhna_from_IBM.md"};function e(n,t,s,_,g,p){return a(),i("div",null,[...t[0]||(t[0]=[o('<p>本文是IBM的Kamoltat (Junior) Sirivadhna关于支持Ceph集群中三个可用区弹性集群的会议总结。</p><p><strong>会议主题</strong>: 支持Ceph集群中的三个可用区弹性集群</p><p><strong>主讲人</strong>: Junior (Kamoltat Sirivadhna)</p><p><strong>会议时间</strong>: 未知</p><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议主要讨论了如何在Ceph集群中支持三个可用区弹性集群，特别是针对传统弹性集群的局限性，以及如何通过扩展到三个可用区来解决这些问题。会议还介绍了当前的进展和未来的行动计划。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>传统弹性集群的问题</strong>:</p><ul><li><strong>网络分区</strong>: 传统弹性集群在网络分区时，由于MON无法形成法定人数，导致集群无法访问。</li><li><strong>数据一致性问题</strong>: 当一个数据中心发生故障时，可能会导致数据不一致或数据丢失。</li></ul></li><li><p><strong>弹性模式的解决方案</strong>:</p><ul><li><strong>引入仲裁站点</strong>: 弹性模式中引入了一个仅包含仲裁MON的站点，用于解决网络分区问题。</li><li><strong>新的配对规则</strong>: 通过要求acting set包含来自两个数据中心的OSD，避免数据一致性问题。</li></ul></li><li><p><strong>扩展到三个可用区的挑战</strong>:</p><ul><li><strong>配对规则的扩展</strong>: 通过引入新的命令<code>pool stretch set</code>，用户可以设置配对规则的配置值，包括跨桶计数和跨桶目标。</li><li><strong>网络分区检测与决策</strong>: 开发网络分区检测功能，用于检测网络分区并根据OSD数量、MON数量和连接性得分等因素选择生存站点。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ol><li><strong>解决网络分区问题</strong>：通过引入仲裁MON和新的配对规则，确保集群在网络分区时仍能正常运行。</li><li><strong>扩展到三个可用区</strong>：通过引入新的配对规则和网络分区检测功能，确保在三个可用区的情况下，集群能够保持高可用性和数据一致性。</li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><strong>网络分区检测功能的开发与测试</strong>：继续开发网络分区检测功能，并确保其在T版本中发布。</li><li><strong>扩展配对规则的实现</strong>：完成对三个可用区的配对规则扩展，并进行充分的测试和验证。</li><li><strong>启发式决策的优化</strong>：进一步优化选择生存站点的启发式方法，确保在各种情况下都能做出最佳决策。</li></ol><h4 id="关键术语" tabindex="-1">关键术语 <a class="header-anchor" href="#关键术语" aria-label="Permalink to &quot;关键术语&quot;">​</a></h4><ul><li><strong>弹性集群</strong> (Stretch Cluster): 具有更大故障域的子集群。</li><li><strong>仲裁站点</strong> (Tiebreaker Site): 用于解决网络分区问题的特殊站点。</li><li><strong>跨桶计数</strong> (peering_cross_bucket_count): 配对规则中的一个变量，要求acting set中至少包含两个不同的故障域。</li><li><strong>跨桶目标</strong> (peering_cross_bucket_target): 限制每个数据中心在acting set中可以包含的OSD数量。</li></ul>',14)])])}const c=r(l,[["render",e]]);export{h as __pageData,c as default};
